const pug = require('pug');
const path = require('path');
require('jest-expect-message');

// Write feedback indicating the test passed all unit tests
function pass(feedback = 'All tests pass') {
  const fs = require('fs');
  fs.writeFileSync('FEEDBACK', `✓ ${feedback}`);
}

// Write feedback indicating a failed comparison test
function err(msg, expected, actual) {
  // Put quotes around strings
  if (typeof expected === 'string') {
    expected = `"${expected}"`;
    actual = `"${actual}"`;
  }

  return `${msg}\n  Expected: ${expected}\n  Found:    ${actual}`
}

function renderTemplate(templatePath, locals = {}) {
  const compiledTemplate = pug.compileFile(path.join(__dirname, templatePath));
  return compiledTemplate(locals);
}

test('Test', async () => { 
  const todoList = ["item1", "item2"];

  renderedHtml = renderTemplate('./views/index.pug', { todoList: todoList });

  const page = document.createElement('html');
  page.innerHTML = renderedHtml;

  const title = page.querySelector('title');
  expect(title, '<title> is missing in rendered HTML').not.toBe(null);

  const expectedTitle = 'To-Do List';
  expect(title.innerHTML,
    err('<title> text in rendered HTML', expectedTitle, title.innerHTML))
    .toBe(expectedTitle);

  const link = page.querySelector('link');
  expect(link, '<link> is missing in rendered HTML').not.toBe(null);

  const expectedRel = 'stylesheet';
  expect(link.rel,
    err('<link> rel attribute in rendered HTML', expectedRel, link.rel))
    .toBe(expectedRel);

  const expectedLinkHref = 'styles.css';
  const actualLinkHref = link.href.replace('http://localhost/', '');
  expect(actualLinkHref,
    err('<link> href attribute in rendered HTML', expectedLinkHref, actualLinkHref))
    .toBe(expectedLinkHref);

  const h1 = page.querySelector('h1');
  expect(h1, '<h1> is missing in rendered HTML').not.toBe(null);

  const expectedH1 = 'To-Do List';
  expect(h1.innerHTML,
    err('<h1> text in rendered HTML', expectedH1, h1.innerHTML))
    .toBe(expectedH1);

  pass();
});

